<?php
// In-app help content (English). Keep slugs and structure identical to ar.php.
$all = '*';
$gov = ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'];
return [
    'topics' => [
        'start' => ['title' => 'Getting started', 'roles' => $all, 'link' => '/', 'summary' => 'A two-minute tour of how the platform is organised and where to find things.',
            'steps' => ['The menu on the side lists the modules you are allowed to use. If a module is missing, your role does not include it.', 'Start from the Dashboard for the overall picture, or from My tasks to see what is waiting for you.', 'Use the question-mark button at the top of any page for help about that page, and the note button to leave yourself a reminder.', 'Everything you change is recorded in the audit log, so you can correct mistakes safely.'],
            'tips' => ['Switch between Arabic and English at the top of the page at any time.', 'Fields marked with a star are required.']],
        'my' => ['title' => 'My tasks', 'roles' => $all, 'link' => '/my', 'summary' => 'One list of everything assigned to you: actions, reports, assessments and your own reminders.',
            'steps' => ['Open My tasks from the top bar. The number on the badge is how many items need attention.', 'Items in red are overdue. Click an item to go straight to it.', 'Reminders you wrote yourself appear here on their due date; tick them off when done.'],
            'tips' => ['Nothing here? Then nothing is waiting for you.']],
        'dashboard' => ['title' => 'Dashboard', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'branch_liaison', 'exec_viewer', 'auditor'], 'link' => '/', 'summary' => 'Live summary of risks, losses and governance status for the period you choose.',
            'steps' => ['Pick a reporting period (or custom dates) at the top and press Apply.', 'Each coloured tile is a link: click it to see the records behind the number.', 'The heat map shows residual risks by likelihood and impact; click a cell to list them.'],
            'tips' => ['If you are limited to a department or branch, the numbers cover only your scope.', 'Red tiles mean something needs action.']],
        'risks' => ['title' => 'Risk register', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'branch_liaison', 'exec_viewer', 'auditor'], 'link' => '/risks', 'summary' => 'Record, rate and follow up operational risks.',
            'steps' => ['Press New risk. Give it a clear title, the department, the category and an owner.', 'Rate it twice: inherent (before controls) and residual (after controls). Choose likelihood and impact; the score and level are calculated for you.', 'Write the existing controls and, if needed, add treatment actions with an owner and deadline.', 'Review the risk regularly; set the next review date so the system can remind you.'],
            'tips' => ['Residual should normally not be higher than inherent. If you must accept a higher value, explain why in the note.', 'Archive a risk instead of deleting it; archived risks can be restored.', 'Use the filters and the export button to prepare lists for meetings.']],
        'incidents' => ['title' => 'Incidents and losses', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'branch_liaison', 'exec_viewer', 'auditor'], 'link' => '/incidents', 'summary' => 'Log operational incidents and near misses with gross loss, recoveries and net loss.',
            'steps' => ['Press New incident. Enter the date it happened, a short description and the department or branch.', 'Enter the gross loss and any recovered amount. The net loss is calculated.', 'Select the root cause and link the risk it relates to, so the risk can be reassessed.', 'Choose the Basel event type and business line, and say where any recovery came from.', 'Close the incident only when root cause, corrective actions and Basel type are recorded. Large losses are escalated automatically, and repeated incidents trigger a review of the linked risks.'],
            'tips' => ['Report near misses too: they are free lessons.', 'Amounts are entered in the bank currency with up to three decimals.']],
        'actions' => ['title' => 'Treatment actions', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'branch_liaison', 'exec_viewer', 'auditor'], 'link' => '/actions', 'summary' => 'All follow-up actions on risks, with deadlines and status.',
            'steps' => ['Filter by status or choose Overdue to see what is late.', 'Open the risk to add or update an action; change its status as work progresses.', 'Mark an action Completed only when the work is done; the completion date is stored.'],
            'tips' => ['Each action has one owner: make sure the right person is named.']],
        'kris' => ['title' => 'Key risk indicators', 'roles' => $gov, 'link' => '/kris', 'summary' => 'Numbers you report regularly that warn you early when a risk is growing.',
            'steps' => ['Open an indicator to see its amber and red thresholds and its history.', 'Add this period’s reading with the date and value. The colour is calculated: green, amber or red.', 'Amber or red readings appear on the dashboard and in the alerts filter.', 'A red or critical reading opens a breach: write the justification and the action plan, and close it when resolved. A reading that jumps by more than 200% needs an explanatory comment.'],
            'tips' => ['“Higher is worse” indicators turn amber/red when the value rises; “lower is worse” ones when it falls.', 'Use the Missing filter to find indicators not reported this cycle.']],
        'appetite' => ['title' => 'Risk appetite', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/appetite', 'summary' => 'Limits the board is willing to accept and what happens when they are exceeded.',
            'steps' => ['Each statement has a metric and a limit. Press Evaluate to compare the current figures with the limits.', 'A breach is recorded automatically; add a note and follow-up and update its status.', 'Breaches are escalated to the committee that approves the appetite.'],
            'tips' => ['Limits are set by management; change them only with approval.']],
        'compliance' => ['title' => 'Compliance obligations', 'roles' => $gov, 'link' => '/compliance', 'summary' => 'Regulatory and internal obligations, their owners, due dates and evidence.',
            'steps' => ['Open an obligation to see its source, owner and due date.', 'Update the status as work progresses and attach evidence (PDF, Office or image files).', 'When a recurring obligation is completed, use Roll forward to create the next cycle.'],
            'tips' => ['Upload evidence as you go: it makes audits easy.', 'Use Export to CSV for regulator reports.']],
        'committees' => ['title' => 'Committee decisions', 'roles' => $gov, 'link' => '/committees', 'summary' => 'Decisions of the Board, Risk, Audit and Sharia committees, with follow-up actions.',
            'steps' => ['Record each decision with the committee, the meeting date and the decision text.', 'Add follow-up actions with an owner and deadline.', 'Update the decision status to Implemented when all actions are done.'],
            'tips' => ['Overdue follow-ups appear on the dashboard and on the owner’s My tasks page.']],
        'policies' => ['title' => 'Policies and procedures', 'roles' => $all, 'link' => '/policies', 'summary' => 'Library of approved policies with version history.',
            'steps' => ['Search or filter to find a policy and open it to read the current version.', 'Authorised staff add a new version with the approval date; old versions are kept and never edited.', 'The review date shows when a policy must be revisited.'],
            'tips' => ['Always read the current approved version, not a saved copy.']],
        'rcsa' => ['title' => 'Risk and control self-assessment (RCSA)', 'roles' => $all, 'link' => '/rcsa', 'summary' => 'Periodic questionnaires where each unit assesses its own risks and controls.',
            'steps' => ['If you are an assessor, open your assigned assessment, answer every question and add comments.', 'Press Save to continue later, or Submit when finished. After submission you cannot edit it.', 'A reviewer approves it or returns it with comments; returned assessments reappear in My tasks.'],
            'tips' => ['You cannot review your own assessment.', 'Managers can schedule assessments to launch automatically each quarter, half-year or year from RCSA schedules; a major incident or a failed key control also launches one.']],
        'reports' => ['title' => 'Reports and export', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'branch_liaison', 'exec_viewer', 'auditor'], 'link' => '/reports', 'summary' => 'Printable reports and CSV downloads.',
            'steps' => ['Choose a report, set the filters and open the print view.', 'Use your browser’s Print and choose Save as PDF to share it.', 'CSV files open in Excel; Arabic text is encoded correctly.'],
            'tips' => ['Exports contain only what you are allowed to see.']],
        'notes' => ['title' => 'Notes and reminders', 'roles' => $all, 'link' => '/notes', 'summary' => 'Private notes to yourself, optionally with a reminder date.',
            'steps' => ['Press the note button on any page, write the note and, if you wish, choose a reminder date.', 'The note remembers which page you were on, so you can jump back to it.', 'On the reminder date it appears in My tasks. Tick it when done.'],
            'tips' => ['Notes are private: nobody else, including administrators, sees them in the application.']],
        'account' => ['title' => 'My account', 'roles' => $all, 'link' => '/account', 'summary' => 'Change your password and your preferred language.',
            'steps' => ['Open My account from the top bar.', 'Choose a strong password (at least 12 characters, not containing your username).', 'Select your preferred language; it is remembered next time.'],
            'tips' => ['If you forget your password, ask the administrator to reset it.']],
        'admin' => ['title' => 'Administration', 'roles' => ['admin', 'risk_manager'], 'link' => '/admin/users', 'summary' => 'Users, departments, branches, scales and system settings.',
            'steps' => ['Users: create accounts, assign a role and (for managers and liaisons) the department or branch.', 'Departments, branches, categories and reporting periods are kept under the same menu.', 'Scales: review likelihood, impact and score bands, then approve the thresholds.', 'Settings and System show the installed version and pending database updates.'],
            'tips' => ['Deactivate a user instead of deleting it so history stays intact.', 'Thresholds installed with the platform are examples: have them approved by the risk committee.']],
        'controls' => ['title' => 'Control library and testing', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/controls', 'summary' => 'The list of controls that reduce risk, who owns them, and independent proof that they work.',
            'steps' => ['Create a control once, then link it to every risk it mitigates (from the control page, or see it on the risk page).', 'Set the type (preventive, detective, corrective), who owns it and how often it must be tested.', 'A different person tests it: press Record a test, choose design or operating, enter the sample and the exceptions found.', 'An Effective result needs evidence attached and zero exceptions. Anything less needs a written conclusion and creates a remediation action on the linked risks.'],
            'tips' => ['You cannot test a control you own: independence is a rule, not a suggestion.', 'Use the filters Never tested and Tests overdue to plan the testing calendar.', 'When a linked control is weak, the risk page warns you to re-check the residual rating.']],
        'sharia' => ['title' => 'Sharia compliance', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/sharia', 'summary' => 'Sharia Supervisory Board rulings, Sharia reviews, non-compliance events and purification of impermissible income.',
            'steps' => ['The rulings register holds every fatwa and board resolution. Search it before approving a product or practice.', 'See something that may breach Sharia rules? Press Report a non-compliance event. High-severity events are escalated to the board automatically.', 'The compliance team starts the Sharia review and records the board decision, including any impermissible income.', 'If income must be purified, transfer it to the approved charity and record the date and beneficiary. Only then can the event be closed.', 'The annual report page summarises rulings, reviews, events and purification for the chosen year.'],
            'tips' => ['Report early and in good faith: unreported breaches are the real risk.', 'Link an event to the ruling that was not followed so patterns become visible.', 'Department managers see only events of their own department.']],
        'bia' => ['title' => 'Business impact analysis and approvals', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/bia', 'summary' => 'Which processes the bank cannot afford to lose, how fast each must recover, and whether the systems behind it can keep that promise.',
            'steps' => ['Register the supporting systems first (how many hours each really needs to recover and how much data it could lose).', 'Add a process: rate the financial, operational, legal and reputation impact from 1 to 5. The highest rating sets its criticality.', 'Enter the objectives: maximum tolerable outage, recovery time (RTO) and recovery point (RPO). RTO cannot exceed the maximum outage.', 'Link the systems the process needs. If any system cannot recover as fast as the process requires, a red box shows the gap and the process cannot be sent for approval.', 'Send it for approval. A different person (risk manager or compliance officer) approves or rejects it from the Approvals page. Approved analyses are reviewed after one year.'],
            'tips' => ['Changing impact or objectives on an approved process returns it to Draft for a fresh approval.', 'Nobody approves their own request: that is the maker-checker rule.', 'The BIA report lists every open recovery gap for the business continuity plan.']],
        'circulars' => ['title' => 'Regulatory circulars', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/circulars', 'summary' => 'Instructions from the regulator: who received them, who must act and what was done.',
            'steps' => ['The compliance team registers each circular with its issuer, dates, summary and the required action, and attaches the original document.', 'It sends the circular to the departments that must act. After sending, the circular is locked.', 'Each department manager opens it from My tasks, confirms receipt and describes the action taken.', 'When every department has acknowledged, the circular closes by itself. Overdue ones appear in My tasks and on the dashboard.'],
            'tips' => ['Link the circular to a compliance obligation to follow the requirement until it is met.', 'You only see circulars sent to your department.']],
        'governance' => ['title' => 'Boards and committees', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/governance', 'summary' => 'Who sits on each board or committee, when it met, who attended and whether it follows its own rules.',
            'steps' => ['Create the board or committee with its type, the minimum meetings per year and the quorum.', 'Add the members and appoint one chair. Meetings cannot be scheduled without a chair.', 'Schedule the meeting with its agenda. After it takes place, tick who attended and write the minutes.', 'The system checks the quorum. A meeting without quorum is flagged because its decisions may be invalid.', 'The compliance report shows, for the year, meetings held against the minimum, quorum failures and average attendance.'],
            'tips' => ['Record decisions under Committee decisions using the same committee type and meeting date: they appear on the meeting page.', 'Only managers can change membership or record meetings.']],
        'import' => ['title' => 'Importing data from CSV', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager'], 'link' => '/import', 'summary' => 'Load many risks, KRI readings or compliance obligations at once from a spreadsheet.',
            'steps' => ['Download the template for what you want to load and fill it in Excel. Keep the first row as it is.', 'Use codes and usernames that already exist (department, category, KRI, owner).', 'Save as CSV (UTF-8) and upload it. The platform checks every row and lists the problems by line.', 'If the file is clean, review the sample and press Import. If even one row has a problem, nothing is saved.'],
            'tips' => ['Fix the file and upload again: nothing is half-imported.', 'You can only import into your own department if you are a department manager.']],
        'recon' => ['title' => 'Loss reconciliation', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/incidents/reconciliation', 'summary' => 'Check that the losses in the incident register agree with the operational-loss entries in the general ledger.',
            'steps' => ['Finance gives you the monthly operational-loss entries as a CSV (period, account, amount, description).', 'Load them from Import data, choosing "General ledger loss entries". A month that is already loaded is refused.', 'Open the reconciliation page: each month shows incident net losses, the ledger total and the difference.', 'Click the incident amount to see the incidents behind it. Unexplained differences mean an unrecorded incident or a wrong ledger booking.'],
            'tips' => ['The administrator can set a tolerance in Settings.', 'Remove and reload a month if the ledger figures were corrected.']],
        'strategy' => ['title' => 'Strategic objectives', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/strategy', 'summary' => 'The bank\'s objectives on a balanced scorecard, with progress and the risks that threaten each one.',
            'steps' => ['Add an objective with its perspective (financial, customers, internal processes, learning), owner, unit, starting value, target and due date.', 'Record progress regularly. The percentage is calculated from the starting value to the target and coloured green (90% or more), amber (60–89%) or red (below 60%).', 'Link the risks from the register that could stop the objective. This shows which objectives are exposed.', 'The scorecard page groups every objective by perspective and prints cleanly for the board.'],
            'tips' => ['For goals where lower is better (cost, incidents) choose "Lower is better": the target must then be below the starting value.', 'Objectives past their due date show a warning until they reach 100%.']],
        'ia' => ['title' => 'Internal audit', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/ia', 'summary' => 'A risk-based annual audit plan, engagements with workpapers, and findings followed until they are closed.',
            'steps' => ['List what can be audited in the Audit universe and rate materiality, regulatory exposure and complexity from 1 to 5. The platform adds the department\'s highest residual risk, the time since the last audit and the last rating, and calculates a priority score.', 'Create the plan for the year. Entities are listed highest priority first; those marked Due must be audited this year. Add an engagement for each with a lead auditor and dates.', 'Record the audit committee approval. The plan is then locked and fieldwork can start.', 'For each test, open a workpaper, record the sample, exceptions and conclusion, and attach evidence. Another auditor must review it: nobody reviews their own work.', 'Write findings with condition, criteria, cause, effect and recommendation. When the report is issued with its rating, every finding goes to its responsible manager.', 'Follow each finding: management responds with an action and a date, reports it as implemented, and the auditor verifies before closing it.'],
            'tips' => ['Findings stay as drafts, visible to auditors only, until the report is issued.', 'Extending a target date is counted and logged, and the original date is kept.', 'The overview shows open high findings, overdue items and the share closed on time.']],
        'ia_findings' => ['title' => 'Answering audit findings', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'dept_manager', 'exec_viewer', 'auditor'], 'link' => '/ia/findings', 'summary' => 'What to do when internal audit raises a finding for your area.',
            'steps' => ['New findings appear in My tasks. You have 14 days to respond.', 'Open the finding, read what was found and why it matters, then write your response, the action you agree to take and a realistic target date.', 'When the work is done, report it as implemented, describe what was done and attach evidence.', 'Internal audit checks the evidence and closes the finding, or returns it with a note if more is needed.'],
            'tips' => ['Only the named responsible manager can respond.', 'If you need more time, ask internal audit before the target date: they record the new date.']],
        'aml' => ['title' => 'Anti-money laundering', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/aml', 'summary' => 'Rate every customer for money-laundering risk across four dimensions, follow due diligence and reviews, and track AML reports.',
            'steps' => ['Review the risk factors first: customer types, products and services, delivery channels and countries, each rated low, medium or high. The supplied list is only an example.', 'Assess a customer by choosing its type, country, products and channels, and tick politically exposed person or possible sanctions match if they apply. The rating, the due-diligence level and the next review date are calculated.', 'The customer page shows how the rating was reached. A different rating can be set only with a written reason, and never below high for a politically exposed person or a sanctions match.', 'Record periodic reviews when they fall due: high every year, medium every two years, low every three years.', 'Link controls from the control library to each dimension: their test results reduce the residual risk on the overview.', 'Register reports to the financial intelligence unit and the regulator with their due dates, and record when they were sent.'],
            'tips' => ['Suspicious transaction reports are confidential: only the AML team can see them.', 'Customers can be loaded from T24 instead of typed in.', 'Changing a factor\'s level re-rates every customer that uses it.']],
        't24' => ['title' => 'Integration with T24', 'roles' => ['admin'], 'link' => '/admin/integrations', 'summary' => 'Load customers and loss ledger entries from the T24 core banking system, by file or through its API.',
            'steps' => ['Download the templates to show the T24 team which columns are needed, and adjust the field mapping to the bank\'s T24 field names.', 'Load an export file, or enter the API address and credentials, test the connection and load directly.', 'Every load is checked first. If any row is wrong nothing is written, and the load history shows the errors by line.', 'Set up the scheduled job (bin/t24-sync.php) with the hosting administrator to load automatically every night.'],
            'tips' => ['T24 codes become AML risk factors through the T24 code field on each factor.', 'Loading the same loss period again replaces it, so nothing is counted twice.', 'The password or token is stored encrypted and never shown again.']],
        'assistant' => ['title' => 'AI assistant and reference library', 'roles' => $all, 'link' => '/assistant', 'summary' => 'Ask questions about AML, compliance, risk, audit and Sharia governance and get answers that cite trusted sources.',
            'steps' => ['Open AI assistant from the menu and type your question in Arabic or English, or pick one of the examples.', 'Read the answer: every point carries a number that links to the source passage, and the source links to the original publication.', 'On a customer, audit finding or obligation page, press "Ask the assistant" to ask about that record. You see exactly which de-identified fields will be sent.', 'If the library does not cover your question, the assistant says so. Ask the compliance team to add the relevant circular or policy to the reference library.'],
            'tips' => ['Never type customer names or numbers: numbers and e-mail addresses are removed automatically, names cannot be.', 'Answers are guidance. Check the original text, especially for Libyan law and Central Bank circulars.', 'Compliance and risk staff can add documents from the reference library or straight from a registered circular.']],
        'framework' => ['title' => 'Framework documents', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/policies/framework', 'summary' => 'The bank\'s charters, frameworks, policies and manuals in one hierarchy, imported from Word, with missing references flagged.',
            'steps' => ['Open Framework documents and import the bank\'s Word files (several at once). The control table of each file gives the code, type, version, classification and approving body.', 'Each document takes its level in the hierarchy: charters 1, risk appetite 2, ERM framework 3, policies 4, manuals 5, methodologies and tools 6, plans and reports 7. A manual is linked to its policy automatically.', 'Codes cited in a document that are not in the register appear as missing references: issue the document or correct the citation.', 'Confidential and secret documents can be opened only by risk, compliance and internal audit. Each import is also added to the reference library for the assistant.'],
            'tips' => ['Importing a new version keeps the previous one in the version history.', 'For a large set, the administrator can run bin/import-documents.php on the server.', 'Never upload the bank\'s documents to a demonstration or public copy of the platform.']],
        'rm' => ['title' => 'Risk function workbench', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/rm', 'summary' => 'The risk function\'s recurring procedures, independent opinions, limit breaches and escalations to the risk committee chair.',
            'steps' => ['The work calendar lists this period\'s task for every recurring procedure of the five sections, with its due date. Complete each with a note or evidence.', 'Write an independent opinion on a financing request, product, change or outsourcing: no objection, conditional, or reservation. Another person reviews it and the risk director issues it.', 'Record the decision taken by the approving body. A decision against a reservation is escalated automatically.', 'Record limit breaches and requests for exceptions. A regulatory breach is escalated at once, and no exception can be granted against a regulatory limit.', 'Follow every escalation until the committee chair\'s response is recorded and the case is closed.'],
            'tips' => ['The opinion is advice, not approval: the approving body keeps its responsibility.', 'The chief executive is informed of escalations unless the case concerns them.', 'Department managers see and answer breaches of their own department only.']],
        'raf' => ['title' => 'Risk appetite framework', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/appetite/framework', 'summary' => 'Board-level appetite metrics with appetite, warning and maximum levels, monitored green, amber and red.',
            'steps' => ['Create the standard set of 49 board metrics in nine categories from the template. They start uncalibrated.', 'Calibrate each metric with the values approved by the board: appetite level, warning limit and maximum, plus formula, source and frequency. Readings are refused until a metric is calibrated.', 'Enter readings. Reaching the warning limit opens an amber notice asking the owner for a preventive plan; reaching the maximum escalates to the risk committee chair.', 'Print or export the notice for each amber or red case, and follow the dashboard quarterly with the committee.'],
            'tips' => ['A lower-level limit may never be looser than the board metric above it.', 'Raising a limit needs an explicit board decision: leaving a breach untreated is not acceptance.']],
        'icaap' => ['title' => 'ICAAP', 'roles' => ['admin', 'risk_manager', 'exec_viewer', 'auditor'], 'link' => '/icaap', 'summary' => 'The annual internal capital adequacy assessment: inputs, material risks, Pillar 2 capital, stress tests, report and approvals.',
            'steps' => ['Create the cycle for the year. Nine phases with checklists and dates are added.', 'Enter capital and risk-weighted assets and the target, warning, trigger and minimum ratios. The ratio is reconciled with the last regulatory return.', 'Assess the 16 risks by impact and likelihood. A risk is material when impact is 4 or more or the score is 10 or more; enter the internal capital and method for each material risk.', 'Enter the three-year profit, distributions, extra provisions and asset growth for the base, moderate and severe scenarios. The capital ratio path and its zone are calculated.', 'Write the report sections, declare, record the committee and board decisions and the submission date. The cycle is then locked.'],
            'tips' => ['A severe scenario below the minimum raises an alert and an escalation.', 'The Word report follows the bank\'s ICAAP report template.']],
        'board_report' => ['title' => 'Quarterly board risk report', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/board-reports', 'summary' => 'Build the quarterly risk report to the board on the standard eleven-section model, approve it and follow its recommendations.',
            'steps' => ['Create the report for the quarter. The seven risk-profile domains are added for assessment.', 'Write the cover letter and the narrative of each section. Suggest dashboard tiles from the platform\'s data and add the framework documents as references.', 'Add key messages, observations, data-quality findings, proposed decisions (marked for information, approval or direction) and recommendations by department with priority and duration.', 'Priority risks, the assessment scale and the quarter\'s operational events are read live from the registers.', 'Submit to the risk committee, record its meeting, then record the board approval. Decisions become board decisions and recommendations become actions owned by each department\'s manager.'],
            'tips' => ['Link a recommendation to a decision code (for example D-1) so it becomes an action under that decision.', 'The approved report is locked; follow-up shows late actions.', 'Print or export to Word in the model\'s order.']],
        'registers' => ['title' => 'Supporting registers', 'roles' => ['admin', 'risk_manager', 'compliance_officer', 'exec_viewer', 'auditor'], 'link' => '/registers', 'summary' => 'Model register, data deliveries, maturity, temporary security acceptances, emerging risks, regulatory requirements and the committee plan.',
            'steps' => ['Open a register from the hub. Each shows open and overdue items.', 'Record data deliveries with their due date; the receipt date marks them on time or late.', 'Record temporary security acceptances with compensating controls and an expiry date: on expiry they are escalated automatically.', 'Break each circular into its requirements, with the responsible department, the risk function\'s role, the output and the evidence, and follow its compliance summary.', 'Add the eight maturity axes or the committee\'s standard annual plan for a year in one step.'],
            'tips' => ['Items you own appear in My tasks when they fall due.', 'Model validations past their date are flagged.']],
        'audit' => ['title' => 'Audit log', 'roles' => ['admin', 'auditor'], 'link' => '/audit', 'summary' => 'Who did what and when.',
            'steps' => ['Filter by user, action or date range.', 'Open an entry to see what changed.', 'Export to CSV for audit work.'],
